import { test, expect } from '../../fixtures';
import { captureApi, restDelete, qaText } from '../_shared/api';
import { saveSession } from '../_shared/session';
import { openChat, sendMessage, NAMES } from './chat-helpers';

test.describe('Взаимный матч (сервер)', () => {
  test.describe.configure({ timeout: 180_000 });
  test('После мэтча личный чат открыт — сообщение free видит user4 @iphone @data (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    const user4 = await asUser('user4');
    const text = qaText('match-mutual');
    let msgId: string | undefined;
    try {
      // free пишет в чат мэтча 2651ee46 (AC 7: после мэтча чат доступен).
      await openChat(free, NAMES.user4);
      const res = await sendMessage(free, text);
      expect(res.status(), await res.text()).toBe(201);
      const body = await res.json().catch(() => null);
      msgId = body && (Array.isArray(body) ? body[0]?.id : body.id) ? String(Array.isArray(body) ? body[0].id : body.id) : undefined;
      await expect(free.getByText(text)).toBeVisible();

      // user4 видит сообщение (realtime или после перезагрузки — без фиксированных пауз).
      await openChat(user4, NAMES.free);
      await expect(async () => {
        if (!(await user4.getByText(text).isVisible())) await user4.reload();
        await expect(user4.getByText(text)).toBeVisible({ timeout: 5_000 });
      }).toPass({ timeout: 60_000 });
    } finally {
      // Очистка QA-AUTO: удалить своё сообщение. Если RLS не разрешает — оно остаётся с префиксом QA-AUTO (в список чистки).
      if (msgId) {
        const api = await captureApi(free).catch(() => undefined);
        if (api) {
          const del = await restDelete(api, `messages?id=eq.${msgId}`);
          if (!del.ok()) test.info().annotations.push({ type: 'cleanup', description: `сообщение ${msgId} «${text}» не удалено (${del.status()}) — в список чистки` });
        }
      }
      await saveSession(free, 'free');
      await saveSession(user4, 'user4');
    }
  });
});
